mapper.select:
select b.*, u.name assignName from business b left join user u on b.user_id = u.id
b.status in (1,2,3)
and b.id = #{req.businessId}
and b.name like CONCAT('%', #{req.name}, '%')
and b.phone like CONCAT('%', #{req.phone}, '%')
and b.status = #{req.status}
and u.name like CONCAT('%', #{req.assignName}, '%')
and b.user_id = #{userId}
order by b.id desc
